+/// Normalizes one co-Z odd-multiple table built from `base`.
+///
+/// Only the last `Z` is inverted; the earlier inverses follow by multiplying
+/// with the chain factors, and the `Z` of 2P is `2Y * Z` of `base`.
+fn normalize_co_z_table(
+    base: ProjectivePoint,
+    (table, factors): &([ProjectivePoint; 8], [FieldElement; 8]),
+) -> [AffinePoint; 8] {
+    let mut out = [AffinePoint::IDENTITY; 8];
+    let Some(mut z_inverse) = table[7].z.invert() else {
+        return out;
+    };
+
+    for k in (1..8).rev() {
+        let z_inverse2 = z_inverse.square();
+        out[k] = AffinePoint {
+            x: table[k].x * z_inverse2,
+            y: table[k].y * z_inverse2 * z_inverse,
+            infinity: false,
+        };
+        z_inverse = z_inverse * factors[k];
+    }
+
+    z_inverse = z_inverse * double(base.y);
+    let z_inverse2 = z_inverse.square();
+    out[0] = AffinePoint {
+        x: base.x * z_inverse2,
+        y: base.y * z_inverse2 * z_inverse,
+        infinity: false,
+    };
+
+    out
+}
